function councilState(id,restart=false){const p=A.init(state);if(!p.council||typeof p.council!=='object'||Array.isArray(p.council))p.council={};let r=p.council[id];const c=COUNCIL_CASES[id];if(restart||!r||!['fund','trust','risk'].every(k=>Number.isFinite(r[k]))||typeof r.node!=='string'||r.node!=='end'&&!Object.hasOwn(c.nodes,r.node)||!Array.isArray(r.history)||r.history.length>12)r=p.council[id]={node:'start',fund:100,trust:50,risk:25,history:[],feedback:'',won:false};return r;}
function showCouncilMenu(){modal(`<span class="eyebrow">董事会推演 · 决策会改变后续情境</span><h2 id="dialogTitle">把知识带进一场真实的取舍。</h2><p>选择会改变预算余量、团队信任和风险暴露；错误决定可能进入补救分支。这里使用原创教学情境，不计为官方考试题。</p><div class="council-case-grid">${Object.entries(COUNCIL_CASES).map(([id,c])=>`<button data-councilcase="${id}" style="--case-image:url('assets/world-${EXAM_DOMAINS[c.domain].zone}.webp')"><span>${councilState(id).won?'✓ 已获议事章':'进入推演'}</span><strong>${c.title}</strong><p>${c.brief}</p></button>`).join('')}</div><div class="actions"><button id="councilBack" class="primary">回到街区</button></div>`,true);document.querySelectorAll('[data-councilcase]').forEach(el=>el.onclick=()=>showCouncil(el.dataset.councilcase));$('councilBack').onclick=close;}
function showCouncil(id){if(!Object.hasOwn(COUNCIL_CASES,id))return;const c=COUNCIL_CASES[id],r=councilState(id),ended=r.node==='end',win=ended&&r.risk<=40&&r.trust>=55&&r.fund>=0;if(win&&!r.won){r.won=true;state.xp+=3;state.resources.coins++;save();}modal(`<span class="eyebrow">${c.title}</span><h2 id="dialogTitle">${ended?(win?'方案得到议事厅支持':'带着反馈，再推演一次'):esc(c.nodes[r.node].text)}</h2><div class="council-meters">${[['fund','预算余量'],['trust','团队信任'],['risk','风险暴露']].map(([k,n])=>`<div><small>${n}</small><strong>${Math.round(r[k])}</strong><i style="--progress:${Math.max(0,Math.min(100,r[k]))}%"></i></div>`).join('')}</div>${r.feedback?`<div class="council-feedback">${esc(r.feedback)}</div>`:''}${ended?`<p>${win?'你保留了可信的依据与适当控制，获得本情境的议事章。重复通关不重复奖励。':'复盘刚才的决定：预算为非负、信任至少55且风险不高于40，方案才会获得支持。'}</p><div class="scroll-list">${r.history.map(h=>`<div class="item-row">${esc(h)}</div>`).join('')}</div>`:`<div class="council-options">${c.nodes[r.node].options.map((o,i)=>`<button data-counciloption="${i}"><span>方案 ${i+1}</span><strong>${esc(o.text)}</strong><em>作出选择 →</em></button>`).join('')}</div>`}<p class="muted">依据：用户学习资料 ${c.reference}。分数与资源是本教学情境的设计参数，不是经验统计或官方评分。</p><div class="actions"><button id="councilMenu">所有情境</button><button id="councilRestart">重新推演这个情境</button></div>`,true);document.querySelectorAll('[data-counciloption]').forEach(el=>el.onclick=()=>{const o=c.nodes[r.node].options[+el.dataset.counciloption];if(!o)return;r.history.push(o.text);['fund','trust','risk'].forEach((k,i)=>r[k]=Math.max(-100,Math.min(150,r[k]+o.delta[i])));r.feedback=o.feedback;r.node=o.next;save();showCouncil(id);});$('councilMenu').onclick=showCouncilMenu;$('councilRestart').onclick=()=>{const won=r.won;councilState(id,true).won=won;showCouncil(id);save();};}
const examNPC=npc;npc=function(i){if(inExam()){if(i===0){showExamAtlas();return;}if(i===1){startExamQuiz();return;}if(i===2){showCouncilMenu();return;}}examNPC(i);};
